repo.donations.py:
"""Donation records."""


class Donation:
    def __init__(self, donor, pounds):
        self.donor = donor
        self.pounds = pounds

    def __repr__(self):
        return "Donation(%r, %r)" % (self.donor, self.pounds)


ROWS = [('pia', 19), ('omar', 16), ('mia', 51), ('mia', 33), ('noor', 17)]


def load_donations():
    """Yield the stored donations one at a time."""
    for donor, pounds in ROWS:
        yield Donation(donor, pounds)

repo.tagged.py:
"""Labels for the pounds of donations."""


def labelled_poundss(donations, labels):
    """Pair each donation's pounds with its label, in order. donations beyond the end of `labels` get the label 'unlabelled'."""
    return [(labels[i], donations[i].pounds) for i in range(len(labels))]


def label_width(labels):
    """Return the length of the longest label, or 0 when there are none."""
    return max((len(text) for text in labels), default=0)
